var i=`0555-muhammar`;var n=`world-0555`;var r=`BH`;var a=`western-asia`;var s=8;var o=44;var u={en:`Muhammar`,ua:`Мухаммар`};var m={en:`A traditional dish from Bahrain, centered on basmati rice. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Бахрейн. Основні складники: рис басматі. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 24 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 24 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:24,i:[[`basmati-rice`,380,`g`],[`water`,750,`ml`],[`ground-cardamom`,4,`g`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 8 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 8 хвилин до м’якості та готовності.`,t:[`simmering`],m:8,i:[[`date-syrup`,150,`ml`],[`white-granulated-sugar`,50,`g`],[`unsalted-butter`,35,`g`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 12 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 12 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:12,i:[]}];var g={slug:i,id:n,country:`BH`,region:a,servings:8,minutes:44,title:u,text:m,steps:d};export{r as country,g as default,n as id,o as minutes,a as region,s as servings,i as slug,d as steps,m as text,u as title};